// Derivado do Foglamp (https://github.com/foglamp-labs/foglamp, apps/web/src/components/app/app-shell.tsx:130-206 e 268-434 @ 2bc3bb5), Apache-2.0, e do painel do lyx-pr-agent (João Vitor Dadas).
// Modificado por joaodadas/lume: só o shell ficou (Project, Range, Foggy, DevBar, HUD, quota e sunset saíram); nav, brand, user e pathname viraram props; Link da registry no lugar de next/link e usePathname; NavUser lê user e aceita userMenu; header mobile h-12 md:hidden com SidebarTrigger e a gaveta fechando ao navegar, como no painel; imports da registry e textos em pt-BR.
"use client";

import { IconChevronRight } from "@tabler/icons-react";
import type * as React from "react";
import { useEffect } from "react";

import { Link } from "@/registry/base-vega/components/link";
import { ThemeSubmenu } from "@/registry/base-vega/components/theme-switcher";
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from "@/registry/base-vega/ui/avatar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/registry/base-vega/ui/dropdown-menu";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/registry/base-vega/ui/sidebar";

import { isActive, type NavItem } from "./nav";
import { NavIcon } from "./nav-icon";

export type AppShellUser = {
  name: string;
  email?: string;
  image?: string;
};

function initials(value: string) {
  return value.slice(0, 2).toUpperCase();
}

// Um item de navegação: SidebarMenuButton renderizando o Link da registry
// (padrão Base UI `render`, nunca asChild). O NavIcon recebe o tile em
// iconClassName e faz o crossfade outline/filled de 100 ms.
function NavLink({ item, pathname }: { item: NavItem; pathname: string }) {
  const active = isActive(pathname, item.href, item.exact);
  return (
    <SidebarMenuItem>
      <SidebarMenuButton isActive={active} render={<Link href={item.href} />}>
        <NavIcon
          icon={item.icon}
          activeIcon={item.activeIcon}
          active={active}
          className={item.iconClassName}
        />
        <span>{item.label}</span>
      </SidebarMenuButton>
    </SidebarMenuItem>
  );
}

// No Foglamp a sessão vinha do authClient e o nome esperava o mount para não
// divergir na hidratação; aqui user é prop, então SSR e cliente já coincidem.
function NavUser({
  user,
  userMenu,
}: {
  user: AppShellUser;
  userMenu?: React.ReactNode;
}) {
  const name = user.name || user.email || "Conta";
  const email = user.email ?? "";
  const image = user.image || undefined;

  return (
    <SidebarMenuItem>
      <DropdownMenu>
        <DropdownMenuTrigger render={<SidebarMenuButton className="pr-1.5" />}>
          <Avatar size="xs">
            <AvatarImage src={image} alt={name} />
            <AvatarFallback>{initials(name)}</AvatarFallback>
          </Avatar>
          {/* min-w-0 lets the flex child shrink so the name can truncate. */}
          <div className="flex min-w-0 flex-1 flex-col text-left text-sm">
            <span className="truncate">{name}</span>
          </div>
          <IconChevronRight className="ml-auto size-3.5 opacity-15" />
        </DropdownMenuTrigger>
        <DropdownMenuContent
          align="end"
          side="right"
          sideOffset={8}
          className="min-w-(--anchor-width) w-fit"
        >
          <div className="flex gap-3 items-center p-2">
            <Avatar size="sm">
              <AvatarImage src={image} alt={name} />
              <AvatarFallback>{initials(name)}</AvatarFallback>
            </Avatar>
            <div className="flex flex-col gap-0.5 pr-1">
              <DropdownMenuLabel className="max-w-56 truncate p-0 text-foreground">
                {name}
              </DropdownMenuLabel>
              {email && (
                <DropdownMenuLabel className="max-w-56 truncate p-0 font-normal">
                  {email}
                </DropdownMenuLabel>
              )}
            </div>
          </div>
          <DropdownMenuSeparator />
          <ThemeSubmenu />
          {/* Itens do app (sair, plano, admin): DropdownMenuItem passados pelo consumidor. */}
          {userMenu}
        </DropdownMenuContent>
      </DropdownMenu>
    </SidebarMenuItem>
  );
}

/** No celular a barra lateral é uma gaveta: fecha sozinha ao trocar de página. */
function CloseOnNavigate({ pathname }: { pathname: string }) {
  const { setOpenMobile } = useSidebar();
  useEffect(() => {
    // pathname é o gatilho: a cada troca de rota a gaveta fecha.
    if (pathname) setOpenMobile(false);
  }, [pathname, setOpenMobile]);
  return null;
}

/**
 * A casca do app: sidebar inset à esquerda, o conteúdo num cartão que flutua
 * sobre o canvas com shadow-(--custom-shadow), scroll em três camadas (h-svh
 * min-h-0 no provider, min-h-0 overflow-hidden no inset, min-h-0 flex-1
 * overflow-y-auto no main) e a coluna da página em flex flex-col gap-4 py-6
 * px-0 pb-16. `pathname` vem de fora (usePathname no Next, useLocation no
 * Router) porque o bloco não importa roteador nenhum.
 */
export function AppShell({
  nav,
  account,
  brand,
  user,
  userMenu,
  pathname,
  children,
}: {
  nav: NavItem[];
  /** Itens do rodapé, acima do menu de conta (no Foglamp: API Keys e Settings). */
  account?: NavItem[];
  /** O que vai no topo da sidebar e no header mobile: marca mais nome. */
  brand: React.ReactNode;
  user?: AppShellUser;
  /** DropdownMenuItem extras do menu de conta, depois do submenu de tema. */
  userMenu?: React.ReactNode;
  pathname: string;
  children: React.ReactNode;
}) {
  const current = [...nav, ...(account ?? [])].find((item) =>
    isActive(pathname, item.href, item.exact),
  );

  return (
    <SidebarProvider className="group/shell relative h-svh min-h-0 overflow-hidden">
      <CloseOnNavigate pathname={pathname} />
      <Sidebar variant="inset">
        <SidebarHeader>
          <SidebarMenu>
            <SidebarMenuItem>
              {/* A geometria do gatilho do ProjectSwitcher (h-8, gap-2, pl-1.75, svg 3.5), sem hover: a marca é só marca. */}
              <div className="flex h-8 w-full min-w-0 items-center gap-2 overflow-hidden px-1 pr-2 pl-1.75 text-left text-sm [&_svg]:size-3.5 [&_svg]:shrink-0">
                {brand}
              </div>
            </SidebarMenuItem>
          </SidebarMenu>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup>
            <SidebarGroupContent>
              <SidebarMenu>
                {nav.map((item) => (
                  <NavLink key={item.href} item={item} pathname={pathname} />
                ))}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>

        <SidebarFooter>
          <SidebarMenu>
            {account?.map((item) => (
              <NavLink key={item.href} item={item} pathname={pathname} />
            ))}
            {user && <NavUser user={user} userMenu={userMenu} />}
          </SidebarMenu>
        </SidebarFooter>
      </Sidebar>

      {/* This wrapper owns the inset's canvas margin so the dev bar can sit
          above it without disturbing the sidebar/Foggy horizontal flex layout.
          With no dev bar in production, the single inset fills it exactly as it
          did before. */}
      <div className="flex min-h-0 min-w-0 flex-1 flex-col gap-2 md:peer-data-[variant=inset]:m-2 md:peer-data-[variant=inset]:ml-0 md:peer-data-[variant=inset]:peer-data-[state=collapsed]:ml-2">
        <SidebarInset className="min-h-0 overflow-hidden transition-shadow duration-200 md:rounded-lg squircle:md:rounded-3xl">
          {/* No celular: barra do topo com o botão da gaveta, a marca e a página atual. */}
          <header className="flex h-12 shrink-0 items-center gap-2 border-b border-border/40 px-3 md:hidden">
            <SidebarTrigger />
            <div className="flex min-w-0 flex-1 items-center gap-2 text-sm font-medium [&_svg]:size-3.5 [&_svg]:shrink-0">
              {brand}
            </div>
            {current && (
              <span className="ml-auto flex shrink-0 items-center gap-1.5 text-xs text-muted-foreground">
                <NavIcon
                  icon={current.icon}
                  activeIcon={current.activeIcon}
                  active
                  className={current.iconClassName}
                />
                {current.label}
              </span>
            )}
          </header>
          {/* The scroll viewport is a plain block with a definite height
              (flex-1 + min-h-0); the flex-column layout lives in a child so the
              scroll container itself never tries to flex-fit its content. */}
          <main className="min-h-0 flex-1 overflow-y-auto">
            <div className="flex flex-col gap-4 py-6 px-0 pb-16">
              {children}
            </div>
          </main>
        </SidebarInset>
      </div>
    </SidebarProvider>
  );
}

// Derivado do Foglamp (https://github.com/foglamp-labs/foglamp, apps/web/src/components/app/app-shell.tsx:213-255 @ 2bc3bb5), Apache-2.0, e do painel do lyx-pr-agent (João Vitor Dadas).
// Modificado por joaodadas/lume: extraído para arquivo próprio, imports da registry e, como no painel, um único glifo quando o ícone não tem variante filled (activeIcon === icon).
import type { Icon } from "@tabler/icons-react";

import { cn } from "@/registry/base-vega/lib/utils";

// Cross-fades the outline icon into its filled variant when the tab goes active.
// Both icons are stacked in the same grid cell so only the glyph opacity tweens;
// the colored chip (`className`, e.g. background + padding + shadow) lives on the
// wrapper so it stays constant across the swap instead of fading in and out.
//
// The wrapper is pinned to the icon footprint (`size-4.5`) and the inner SVGs
// fill its padded content box (`size-full`, overriding the sidebar's forced
// `[&_svg]:size-4.5`). This keeps a chip item's outer size at 18px with the glyph
// inset by its padding — matching the original single-icon geometry — rather than
// letting the padding grow the chip around two full-size icons.
//
// Nem todo ícone do Tabler tem o par Filled; quando o item repete o mesmo
// componente nos dois campos, fica um glifo só, sempre visível.
export function NavIcon({
  icon: OutlineIcon,
  activeIcon: ActiveIcon,
  active,
  className,
}: {
  icon: Icon;
  activeIcon: Icon;
  active: boolean;
  className?: string;
}) {
  const hasFilled = ActiveIcon !== OutlineIcon;
  return (
    <span
      className={cn(
        "grid size-4.5 place-items-center [&_svg]:size-full!",
        className,
      )}
    >
      <OutlineIcon
        className={cn(
          "[grid-area:1/1] transition-opacity duration-100 ease-in-out",
          active && hasFilled ? "opacity-0" : "opacity-100",
        )}
      />
      {hasFilled && (
        <ActiveIcon
          className={cn(
            "[grid-area:1/1] transition-opacity duration-100 ease-in-out",
            active ? "opacity-100" : "opacity-0",
          )}
        />
      )}
    </span>
  );
}

// Derivado do Foglamp (https://github.com/foglamp-labs/foglamp, apps/web/src/components/app/nav.ts e apps/web/src/components/app/app-shell.tsx:208-211 @ 2bc3bb5), Apache-2.0.
// Modificado por joaodadas/lume: a tabela de rotas do Foglamp saiu (cada app passa a sua), href vira string em vez de Route do Next, a receita do tile virou navTile(cor) com as nove cores por extenso, isActive veio do app-shell e ganhou o flag exact no lugar do caso fixo de /settings.
import type { Icon } from "@tabler/icons-react";

export type NavItem = {
  /** Rota escrita como string ("/pedidos"), nunca o tipo Route do Next. */
  href: string;
  label: string;
  /** Outline icon, shown when the tab is inactive. */
  icon: Icon;
  /** Filled icon, shown when the tab is active. */
  activeIcon: Icon;
  /** Optional Tailwind class(es) for the icon, e.g. "text-blue-500". */
  iconClassName?: string;
  /** Só casa o pathname exato. Use quando um item é prefixo de outro, como
   * "/configuracoes" ao lado de "/configuracoes/equipe" (o caso que no Foglamp
   * era fixo em código para /settings). */
  exact?: boolean;
};

export type NavTileColor =
  | "rose"
  | "emerald"
  | "orange"
  | "sky"
  | "fuchsia"
  | "yellow"
  | "violet"
  | "blue"
  | "amber";

// A receita do tile colorido do ícone de navegação (nav.ts:44 do Foglamp):
// fundo {cor}-100 no claro e {cor}-950 no escuro, raio de 5px (xl no squircle),
// p-0.5, glifo em {cor}-500, anel interno de 1px a 14% da cor mais uma sombra
// curta a 25%; no escuro cai para a sombra neutra. Os rgba são o {cor}-500 do
// Tailwind, os mesmos do nav.ts e do span-type.tsx. Uma string completa por
// cor, sem interpolação, para o Tailwind enxergar cada classe.
const TILES: Record<NavTileColor, string> = {
  rose: "bg-rose-100 dark:bg-rose-950 rounded-[5px] squircle:rounded-xl p-0.5 corner-squircle text-rose-500 shadow-[inset_0_0_0_1px_rgba(244,63,94,0.14),0_2px_6px_-2px_rgba(244,63,94,0.25)] dark:shadow-(--custom-shadow)",
  emerald:
    "bg-emerald-100 dark:bg-emerald-950 rounded-[5px] squircle:rounded-xl p-0.5 corner-squircle text-emerald-500 shadow-[inset_0_0_0_1px_rgba(16,185,129,0.14),0_2px_6px_-2px_rgba(16,185,129,0.25)] dark:shadow-(--custom-shadow)",
  orange:
    "bg-orange-100 dark:bg-orange-950 rounded-[5px] squircle:rounded-xl p-0.5 corner-squircle text-orange-500 shadow-[inset_0_0_0_1px_rgba(249,115,22,0.14),0_2px_6px_-2px_rgba(249,115,22,0.25)] dark:shadow-(--custom-shadow)",
  sky: "bg-sky-100 dark:bg-sky-950 rounded-[5px] squircle:rounded-xl p-0.5 corner-squircle text-sky-500 shadow-[inset_0_0_0_1px_rgba(14,165,233,0.14),0_2px_6px_-2px_rgba(14,165,233,0.25)] dark:shadow-(--custom-shadow)",
  fuchsia:
    "bg-fuchsia-100 dark:bg-fuchsia-950 rounded-[5px] squircle:rounded-xl p-0.5 corner-squircle text-fuchsia-500 shadow-[inset_0_0_0_1px_rgba(217,70,239,0.14),0_2px_6px_-2px_rgba(217,70,239,0.25)] dark:shadow-(--custom-shadow)",
  yellow:
    "bg-yellow-100 dark:bg-yellow-950 rounded-[5px] squircle:rounded-xl p-0.5 corner-squircle text-yellow-500 shadow-[inset_0_0_0_1px_rgba(234,179,8,0.14),0_2px_6px_-2px_rgba(234,179,8,0.25)] dark:shadow-(--custom-shadow)",
  violet:
    "bg-violet-100 dark:bg-violet-950 rounded-[5px] squircle:rounded-xl p-0.5 corner-squircle text-violet-500 shadow-[inset_0_0_0_1px_rgba(139,92,246,0.14),0_2px_6px_-2px_rgba(139,92,246,0.25)] dark:shadow-(--custom-shadow)",
  blue: "bg-blue-100 dark:bg-blue-950 rounded-[5px] squircle:rounded-xl p-0.5 corner-squircle text-blue-500 shadow-[inset_0_0_0_1px_rgba(59,130,246,0.14),0_2px_6px_-2px_rgba(59,130,246,0.25)] dark:shadow-(--custom-shadow)",
  amber:
    "bg-amber-100 dark:bg-amber-950 rounded-[5px] squircle:rounded-xl p-0.5 corner-squircle text-amber-500 shadow-[inset_0_0_0_1px_rgba(245,158,11,0.14),0_2px_6px_-2px_rgba(245,158,11,0.25)] dark:shadow-(--custom-shadow)",
};

/** Devolve a string literal do tile colorido para `iconClassName`. Itens de
 * conta (sem tile) usam "text-muted-foreground/70", como no Foglamp. */
export function navTile(color: NavTileColor): string {
  return TILES[color];
}

/** Ativo por igualdade ou por prefixo de segmento ("/pedidos" ativa em
 * "/pedidos/42", não em "/pedidosx"). Com `exact`, só igualdade. A raiz "/"
 * só casa exata, senão ficaria acesa em toda página. */
export function isActive(pathname: string, href: string, exact = false) {
  if (exact || href === "/") return pathname === href;
  return pathname === href || pathname.startsWith(`${href}/`);
}

/** Look up a nav item by its href, e.g. to drive a page-header breadcrumb. */
export function navItem(items: NavItem[], href: string): NavItem | undefined {
  return items.find((item) => item.href === href);
}
